CREATE SCHEMA lablogistics;
SET search_path TO lablogistics, public;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL,
 email text, full_name text, phone text, roles text[] NOT NULL DEFAULT '{}', qualifications text[] NOT NULL DEFAULT '{}',
 certifications jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, assigned_location_id uuid,
 available boolean NOT NULL DEFAULT true, capacity_units integer NOT NULL DEFAULT 4, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sessions (token text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, active_role text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE sample_types (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, qualified_collector_required boolean NOT NULL,
 required_qualification text, container_type text NOT NULL, temperature_min_c numeric NOT NULL, temperature_max_c numeric NOT NULL,
 incompatible_sample_types uuid[] NOT NULL DEFAULT '{}', requires_cooled_route boolean NOT NULL DEFAULT false,
 batching_allowed boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE locations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, latitude numeric NOT NULL, longitude numeric NOT NULL,
 coverage_km numeric NOT NULL DEFAULT 5 CHECK(coverage_km > 0 AND coverage_km <= 5), handling_minutes integer NOT NULL DEFAULT 0,
 active boolean NOT NULL DEFAULT true, functions jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE connections (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_location_id uuid NOT NULL REFERENCES locations(id), to_location_id uuid NOT NULL REFERENCES locations(id),
 travel_minutes integer NOT NULL, cost_units numeric NOT NULL, cooled boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true,
 UNIQUE(from_location_id,to_location_id)
);
CREATE TABLE capacities (
 resource_id uuid PRIMARY KEY, capacity_units integer NOT NULL DEFAULT 0, reserved_units integer NOT NULL DEFAULT 0,
 cooled_capacity_units integer NOT NULL DEFAULT 0, cooled_reserved_units integer NOT NULL DEFAULT 0,
 CHECK(reserved_units <= capacity_units), CHECK(cooled_reserved_units <= cooled_capacity_units)
);
CREATE TABLE laboratory_acceptance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), laboratory_id uuid NOT NULL REFERENCES locations(id), sample_type_id uuid NOT NULL REFERENCES sample_types(id), accepts boolean NOT NULL, UNIQUE(laboratory_id,sample_type_id));
CREATE TABLE requests (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES users(id), origin jsonb NOT NULL, origin_type text NOT NULL,
 origin_node_id uuid, requested_at timestamptz NOT NULL, delivery_deadline timestamptz NOT NULL, earliest_collection_at timestamptz NOT NULL,
 latest_collection_at timestamptz NOT NULL, sample_type_id uuid NOT NULL REFERENCES sample_types(id), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE journeys (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_journey_id uuid, plan_version integer NOT NULL DEFAULT 1, route_mode text NOT NULL DEFAULT 'direct',
 status text NOT NULL DEFAULT 'planned', target_laboratory_id uuid, estimated_delivery_at timestamptz, total_cost_units numeric NOT NULL DEFAULT 0,
 ordered_stops jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE samples (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES requests(id), requester_id uuid NOT NULL REFERENCES users(id),
 sample_type_id uuid NOT NULL REFERENCES sample_types(id), container_type text NOT NULL, temperature_min_c numeric NOT NULL,
 temperature_max_c numeric NOT NULL, incompatible_sample_types uuid[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'requested',
 serviceability text NOT NULL, serviceability_reason text, active_journey_id uuid REFERENCES journeys(id), target_laboratory_id uuid,
 sealed boolean NOT NULL DEFAULT false, current_holder_id uuid, received_laboratory_id uuid, exception jsonb,
 latest_location jsonb, location_recorded_at timestamptz, already_sealed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE journey_samples (journey_id uuid REFERENCES journeys(id) ON DELETE CASCADE, sample_id uuid REFERENCES samples(id), PRIMARY KEY(journey_id,sample_id));
CREATE TABLE assignments (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journey_id uuid REFERENCES journeys(id), sample_id uuid REFERENCES samples(id), kind text NOT NULL,
 worker_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'offered', sequence integer NOT NULL DEFAULT 1,
 from_location_id uuid, to_location_id uuid, node_id uuid, laboratory_id uuid, offer_expires_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz
);
CREATE INDEX assignments_worker_idx ON assignments(worker_id,status);
CREATE TABLE handoffs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sample_id uuid NOT NULL REFERENCES samples(id), from_assignment_id uuid, to_assignment_id uuid,
 sender_id uuid NOT NULL, receiver_id uuid NOT NULL, sender_confirmed boolean NOT NULL DEFAULT false, receiver_confirmed boolean NOT NULL DEFAULT false,
 status text NOT NULL DEFAULT 'pending', initiated_at timestamptz NOT NULL, confirmed_at timestamptz
);
CREATE TABLE timeline (
 id bigserial PRIMARY KEY, entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, actor_id text NOT NULL,
 role text NOT NULL, success boolean NOT NULL DEFAULT true, details jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX timeline_entity_idx ON timeline(entity_type,entity_id,occurred_at);
CREATE TABLE audits (
 id bigserial PRIMARY KEY, actor_id text NOT NULL, actor_role text NOT NULL, action text NOT NULL, entity_type text NOT NULL,
 entity_id text NOT NULL, success boolean NOT NULL, details jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audits_search_idx ON audits(entity_type,entity_id,action,occurred_at DESC);
CREATE TABLE realtime_events (id bigserial PRIMARY KEY, type text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency (user_id uuid NOT NULL, operation text NOT NULL, key text NOT NULL, response jsonb NOT NULL, status integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,operation,key));
CREATE TABLE serviceability_versions (version integer PRIMARY KEY, status text NOT NULL, computed_at timestamptz NOT NULL, network_revision integer NOT NULL);
