{"command":"create","path":"/workspace/backend/main.go","file_text":"package main

import (
 "context"
 "encoding/json"
 "errors"
 "fmt"
 "log"
 "net/http"
 "os"
 "path/filepath"
 "strings"
 "time"

 "github.com/jackc/pgx/v5/pgxpool"
 "golang.org/x/crypto/bcrypt"
)

type App struct { db *pgxpool.Pool; frontend string }
type User struct { ID, Username, FullName, ActiveRole string; Roles []string }
type ctxKey string
const userKey ctxKey = "user"

func main() {
 ctx:=context.Background(); url:=os.Getenv("DATABASE_URL"); if url=="" { log.Fatal("DATABASE_URL is required") }
 cfg,err:=pgxpool.ParseConfig(url); if err!=nil { log.Fatal(err) }; cfg.ConnConfig.RuntimeParams["search_path"]="lablogistics,public"
 db,err:=pgxpool.NewWithConfig(ctx,cfg); if err!=nil { log.Fatal(err) }; defer db.Close()
 if err=db.Ping(ctx); err!=nil { log.Fatal(err) }
 app:=&App{db:db,frontend:env("FRONTEND_DIR","frontend/dist")}; if err=app.ensureAdmin(ctx); err!=nil { log.Fatal(err) }
 srv:=&http.Server{Addr:"127.0.0.1:8080",Handler:app.routes(),ReadHeaderTimeout:10*time.Second}
 log.Printf("LabFlow listening on %s",srv.Addr); log.Fatal(srv.ListenAndServe())
}
func env(k,d string) string { if v:=os.Getenv(k); v!="" { return v }; return d }
func (a *App) ensureAdmin(ctx context.Context) error {
 var n int; if err:=a.db.QueryRow(ctx,"select count(*) from users").Scan(&n); err!=nil{return err}; if n>0{return nil}
 u,p:=os.Getenv("ADMIN_USERNAME"),os.Getenv("ADMIN_PASSWORD"); if u==""||p=="" { return errors.New("ADMIN_USERNAME and ADMIN_PASSWORD required for first start") }
 h,_:=bcrypt.GenerateFromPassword([]byte(p),bcrypt.DefaultCost)
 _,err:=a.db.Exec(ctx,"insert into users(username,password_hash,full_name,roles) values($1,$2,$3,$4)",u,string(h),"System Administrator",[]string{"administrator"}); return err
}
func (a *App) routes() http.Handler {
 api:=http.HandlerFunc(a.dispatch); mux:=http.NewServeMux(); mux.Handle("/api/",a.auth(api)); mux.HandleFunc("/ready",a.ready)
 fs:=http.FileServer(http.Dir(a.frontend)); mux.HandleFunc("/maps/bangalore.pmtiles",func(w http.ResponseWriter,r *http.Request){http.ServeFile(w,r,"frontend/public/maps/bangalore.pmtiles")})
 mux.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){ p:=filepath.Join(a.frontend,filepath.Clean(r.URL.Path)); if st,e:=os.Stat(p); e==nil&&!st.IsDir(){fs.ServeHTTP(w,r);return}; http.ServeFile(w,r,filepath.Join(a.frontend,"index.html")) })
 return cors(mux)
}
func cors(next http.Handler) http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("Access-Control-Allow-Origin","*");w.Header().Set("Access-Control-Allow-Headers","Authorization, Content-Type");w.Header().Set("Access-Control-Allow-Methods","GET, POST, OPTIONS");if r.Method=="OPTIONS"{w.WriteHeader(204);return};next.ServeHTTP(w,r)})}
func (a *App) auth(next http.Handler) http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
 if r.URL.Path=="/api/authenticate-user"{next.ServeHTTP(w,r);return}
 tok:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer "); if tok==""{fail(w,401,"unauthorized","Authentication required");return}
 var u User; if err:=a.db.QueryRow(r.Context(),`select u.id,u.username,coalesce(u.full_name,''),u.roles,s.active_role from sessions s join users u on u.id=s.user_id where s.token=$1 and u.active`,tok).Scan(&u.ID,&u.Username,&u.FullName,&u.Roles,&u.ActiveRole);err!=nil{fail(w,401,"unauthorized","Invalid session");return}
 next.ServeHTTP(w,r.WithContext(context.WithValue(r.Context(),userKey,&u)))
})}
func current(r *http.Request)*User{u,_:=r.Context().Value(userKey).(*User);return u}
func has(xs []string,x string)bool{for _,v:=range xs{if v==x{return true}};return false}
func requireRole(w http.ResponseWriter,r *http.Request,roles ...string) (*User,bool){u:=current(r);if u==nil{fail(w,401,"unauthorized","Authentication required");return nil,false};if u.ActiveRole==""{fail(w,409,"role_not_selected","Select an active role");return nil,false};for _,v:=range roles{if u.ActiveRole==v{return u,true}};fail(w,403,"forbidden","The active role cannot perform this action");return nil,false}
func decode(w http.ResponseWriter,r *http.Request,v any)bool{d:=json.NewDecoder(http.MaxBytesReader(w,r.Body,1<<20));d.DisallowUnknownFields();if err:=d.Decode(v);err!=nil{fail(w,400,"invalid_json","Invalid request body");return false};return true}
func send(w http.ResponseWriter,status int,data any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(map[string]any{"data":data})}
func fail(w http.ResponseWriter,status int,code,msg string){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(map[string]string{"error":msg,"code":code})}
func (a *App) ready(w http.ResponseWriter,r *http.Request){if r.Method!="GET"{fail(w,405,"method_not_allowed","Method not allowed");return};if a.db.Ping(r.Context())!=nil{w.WriteHeader(503);json.NewEncoder(w).Encode(map[string]string{"status":"starting"});return};w.Header().Set("Content-Type","application/json");json.NewEncoder(w).Encode(map[string]string{"status":"ready"})}
func (a *App) dispatch(w http.ResponseWriter,r *http.Request){
 if r.Method!="GET"&&r.Method!="POST"{fail(w,405,"method_not_allowed","Method not allowed");return}
 p:=r.URL.Path
 if strings.HasPrefix(p,"/api/read-sample-state/"){a.readSampleState(w,r,strings.TrimPrefix(p,"/api/read-sample-state/"));return}
 if strings.HasPrefix(p,"/api/read-user/"){a.readUser(w,r,strings.TrimPrefix(p,"/api/read-user/"));return}
 handlers:=map[string]func(http.ResponseWriter,*http.Request){
 "/api/authenticate-user":a.login,"/api/select-active-role":a.selectRole,"/api/ui/bootstrap":a.bootstrap,"/api/check-serviceability":a.serviceability,
 "/api/create-collection-request":a.createRequest,"/api/ingest-presealed-sample":a.ingestPresealed,"/api/list-role-work":a.roleWork,
 "/api/read-sample-lifecycle":a.readLifecycle,"/api/read-journey-plan":a.readJourney,"/api/read-operations-state":a.operations,
 "/api/read-serviceability-snapshot":a.serviceabilitySnapshot,"/api/search-audit-trail":a.searchAudit,"/api/events":a.events,
 "/api/create-user":a.createUser,"/api/update-user-access":a.updateUser,"/api/create-location":a.createLocation,"/api/update-location":a.updateLocation,
 "/api/create-connection":a.createConnection,"/api/set-location-status":a.setLocationStatus,"/api/set-location-function-status":a.setLocationFunction,
 "/api/set-connection-status":a.setConnectionStatus,"/api/configure-capacity":a.configureCapacity,"/api/configure-laboratory-acceptance":a.configureLab,
 "/api/create-sample-type":a.createSampleType,"/api/update-sample-type":a.updateSampleType,"/api/set-worker-availability":a.setAvailability,
 "/api/accept-assignment":a.acceptAssignment,"/api/decline-assignment":a.declineAssignment,"/api/record-worker-location":a.recordLocation,
 "/api/collect-and-seal-sample":a.collectSeal,"/api/update-assignment-progress":a.assignmentProgress,"/api/initiate-handoff":a.initiateHandoff,
 "/api/confirm-handoff":a.confirmHandoff,"/api/record-handling-checkpoint":a.handlingCheckpoint,"/api/confirm-laboratory-receipt":a.labReceipt,
 "/api/record-laboratory-exception":a.labException,"/api/cancel-journey":a.cancelJourney,"/api/edit-active-plan":a.editPlan,
 "/api/reroute-journey":a.rerouteJourney,"/api/split-journey":a.splitJourney,"/api/merge-journeys":a.mergeJourneys,"/api/report-disruption":a.disruption,
