func (a *App) lockPlan(w http.ResponseWriter,r *http.Request,id string,expected int)(*User,bool){u,ok:=requireRole(w,r,"administrator","dispatcher");if !ok{return nil,false};var ver int;var status string;if a.db.QueryRow(r.Context(),"select plan_version,status from journeys where id=$1",id).Scan(&ver,&status)!=nil{fail(w,404,"not_found","Journey not found");return nil,false};if ver!=expected{fail(w,409,"stale_plan","Journey plan version changed");return nil,false};if status=="cancelled"||status=="completed"{fail(w,409,"inactive_plan","Journey is not active");return nil,false};return u,true}
func (a *App) cancelJourney(w http.ResponseWriter,r *http.Request){var q planInput;if !decode(w,r,&q){return};u,ok:=a.lockPlan(w,r,q.JourneyID,q.Expected);if !ok{return};samples:=[]string{};rows,_:=a.db.Query(r.Context(),"select sample_id::text from journey_samples where journey_id=$1",q.JourneyID);if rows!=nil{for rows.Next(){var x string;rows.Scan(&x);samples=append(samples,x)};rows.Close()};tx,_:=a.db.Begin(r.Context());_,_=tx.Exec(r.Context(),"update journeys set status='cancelled',plan_version=plan_version+1 where id=$1",q.JourneyID);_,_=tx.Exec(r.Context(),"update assignments set status='cancelled' where journey_id=$1 and status not in('completed','declined')",q.JourneyID);_,_=tx.Exec(r.Context(),"update samples set status='cancelled' where active_journey_id=$1 and status<>'received'",q.JourneyID);_ = tx.Commit(r.Context());a.audit(r.Context(),u,"journey_cancelled","journey",q.JourneyID,true,map[string]any{"reason":q.Reason});send(w,201,map[string]any{"journeyId":q.JourneyID,"status":"cancelled","sampleIds":samples})}
func (a *App) editPlan(w http.ResponseWriter,r *http.Request){var q planInput;if !decode(w,r,&q){return};u,ok:=a.lockPlan(w,r,q.JourneyID,q.Expected);if !ok{return};if q.ChangeType=="cancel_work"{_,_=a.db.Exec(r.Context(),"update assignments set status='cancelled' where journey_id=$1 and status not in('completed','declined')",q.JourneyID)};if stops,yes:=q.Changes["orderedStops"];yes{b,_:=json.Marshal(stops);_,_=a.db.Exec(r.Context(),"update journeys set ordered_stops=$2,plan_version=plan_version+1 where id=$1",q.JourneyID,b)}else{_,_=a.db.Exec(r.Context(),"update journeys set plan_version=plan_version+1 where id=$1",q.JourneyID)};a.audit(r.Context(),u,"journey_plan_edited","journey",q.JourneyID,true,map[string]any{"changeType":q.ChangeType});send(w,201,a.plan(r,q.JourneyID))}
func (a *App) rerouteJourney(w http.ResponseWriter,r *http.Request){var q planInput;if !decode(w,r,&q){return};u,ok:=a.lockPlan(w,r,q.JourneyID,q.Expected);if !ok{return};var replacement string;err:=a.db.QueryRow(r.Context(),`insert into journeys(parent_journey_id,plan_version,route_mode,status,target_laboratory_id,estimated_delivery_at,total_cost_units,ordered_stops) select id,1,route_mode,'planned',target_laboratory_id,estimated_delivery_at,total_cost_units,ordered_stops from journeys where id=$1 returning id`,q.JourneyID).Scan(&replacement);if err!=nil{fail(w,409,"no_valid_route","No replacement route available");return};_,_=a.db.Exec(r.Context(),`insert into journey_samples select $2,sample_id from journey_samples where journey_id=$1;update journeys set status='replaced',plan_version=plan_version+1 where id=$1;update samples set active_journey_id=$2 where active_journey_id=$1`,q.JourneyID,replacement);a.audit(r.Context(),u,"journey_rerouted","journey",q.JourneyID,true,map[string]any{"replacementPlanId":replacement});send(w,201,map[string]any{"journeyId":q.JourneyID,"replanStatus":"replaced","replacementPlanId":replacement,"replacementJourney":a.plan(r,replacement)})}
func (a *App) splitJourney(w http.ResponseWriter,r *http.Request){var q planInput;if !decode(w,r,&q){return};u,ok:=a.lockPlan(w,r,q.JourneyID,q.Expected);if !ok{return};if len(q.SampleIDs)==0{fail(w,409,"invalid_split","Choose samples to split");return};var split string;if a.db.QueryRow(r.Context(),`insert into journeys(parent_journey_id,route_mode,status,target_laboratory_id,estimated_delivery_at,total_cost_units,ordered_stops) select id,route_mode,'planned',target_laboratory_id,estimated_delivery_at,total_cost_units,ordered_stops from journeys where id=$1 returning id`,q.JourneyID).Scan(&split)!=nil{fail(w,409,"invalid_split","Cannot split journey");return};for _,sid:=range q.SampleIDs{_,_=a.db.Exec(r.Context(),"delete from journey_samples where journey_id=$1 and sample_id=$2;insert into journey_samples values($3,$2);update samples set active_journey_id=$3 where id=$2 and active_journey_id=$1",q.JourneyID,sid,split)};_,_=a.db.Exec(r.Context(),"update journeys set plan_version=plan_version+1 where id=$1",q.JourneyID);a.audit(r.Context(),u,"journey_split","journey",q.JourneyID,true,map[string]any{"splitJourneyId":split});send(w,201,map[string]any{"journey":a.plan(r,q.JourneyID),"splitJourney":a.plan(r,split)})}
func (a *App) mergeJourneys(w http.ResponseWriter,r *http.Request){var q planInput;if !decode(w,r,&q){return};if q.TargetID==""{q.TargetID=q.JourneyID};u,ok:=a.lockPlan(w,r,q.TargetID,q.Expected);if !ok{return};for _,source:=range q.SourceIDs{_,_=a.db.Exec(r.Context(),`insert into journey_samples select $1,sample_id from journey_samples where journey_id=$2 on conflict do nothing;update samples set active_journey_id=$1 where active_journey_id=$2;update journeys set status='merged' where id=$2`,q.TargetID,source)};_,_=a.db.Exec(r.Context(),"update journeys set route_mode='batched',plan_version=plan_version+1 where id=$1",q.TargetID);a.audit(r.Context(),u,"journeys_merged","journey",q.TargetID,true,map[string]any{"sources":q.SourceIDs});send(w,201,a.plan(r,q.TargetID))}
