{"command":"create","path":"/workspace/frontend/src/main.tsx","file_text":"import React, {FormEvent, useEffect, useMemo, useRef, useState} from 'react';
import {createRoot} from 'react-dom/client';
import maplibregl from 'maplibre-gl';
import {Protocol} from 'pmtiles';
import {Activity, AlertTriangle, Archive, Beaker, Boxes, ChevronRight, ClipboardList, FlaskConical, Gauge, History, LogOut, Map, MapPin, Menu, Network, PackageCheck, RefreshCw, Route, Search, ShieldCheck, Thermometer, UserRound, Users, X} from 'lucide-react';
import 'maplibre-gl/dist/maplibre-gl.css';
import './styles.css';

type AnyObj=Record<string,any>;
type Bootstrap={user:{userId:string;username:string;fullName?:string;roles:string[];activeRole:string;roleSelectionRequired:boolean};serverTime:string;requesterSamples?:AnyObj[];operations?:AnyObj};
const roleNames:Record<string,string>={administrator:'Administrator',dispatcher:'Dispatcher',requester:'Requester',collection_professional:'Collection professional',delivery_partner:'Relay courier',node_handler:'Node handler',laboratory_team:'Laboratory intake'};
const statusLabel=(v:string='unknown')=>v.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const fmt=(v?:string)=>v?new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';

async function api(path:string,body?:unknown,method?:string){const token=localStorage.getItem('labflow_token');const res=await fetch(path,{method:method||((body===undefined)?'GET':'POST'),headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:body===undefined?undefined:JSON.stringify(body)});const json=await res.json().catch(()=>({error:'Unexpected server response'}));if(!res.ok)throw new Error(json.error||json.code||'Request failed');return json.data}
function Badge({value,tone}:{value:string,tone?:string}){return <span className={`badge ${tone||value}`}>{statusLabel(value)}</span>}
function Empty({title,detail}:{title:string;detail:string}){return <div className="empty"><div className="empty-icon"><Archive size={22}/></div><strong>{title}</strong><p>{detail}</p></div>}
function Toast({message,onClose}:{message:string;onClose:()=>void}){useEffect(()=>{const t=setTimeout(onClose,4500);return()=>clearTimeout(t)},[message]);return <div role="status" className="toast"><PackageCheck size={18}/><span>{message}</span><button aria-label="Dismiss notification" onClick={onClose}><X size={16}/></button></div>}

function Login({onLogin}:{onLogin:()=>void}){const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const d=await api('/api/authenticate-user',{username,password});localStorage.setItem('labflow_token',d.sessionToken);onLogin()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <main className="login-shell"><section className="login-brand"><div className="brand-mark large"><FlaskConical/></div><div><span className="eyebrow light">Clinical logistics, connected</span><h1>Every sample.<br/>Every handoff.<br/><em>Accounted for.</em></h1><p>One operational view from collection through laboratory receipt, with secure custody at every step.</p></div><div className="trust-row"><span><ShieldCheck/>Auditable custody</span><span><Thermometer/>Handling compliance</span><span><Route/>Live routing</span></div></section><section className="login-panel"><form className="login-card" onSubmit={submit}><div className="mobile-logo"><FlaskConical/> LabFlow</div><span className="eyebrow">Secure operations portal</span><h2>Welcome back</h2><p>Sign in to continue under your assigned role.</p>{error&&<div role="alert" className="alert error"><AlertTriangle size={17}/><span>{error}</span></div>}<label>Username<input aria-label="Username" autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} required placeholder="Enter your username"/></label><label>Password<input aria-label="Password" autoComplete="current-password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required placeholder="Enter your password"/></label><button className="primary full" disabled={busy}>{busy?<><RefreshCw className="spin"/>Signing in…</>:'Sign in securely'} </button><div className="login-foot"><ShieldCheck size={15}/>Protected clinical operations environment</div></form></section></main>}

function RolePicker({boot,onDone}:{boot:Bootstrap;onDone:()=>void}){const [choice,setChoice]=useState(boot.user.activeRole||boot.user.roles[0]||'');const [error,setError]=useState('');async function apply(){try{await api('/api/select-active-role',{role:choice});onDone()}catch(e){setError((e as Error).message)}}return <div className="modal-backdrop"><section role="dialog" aria-labelledby="role-title" className="role-modal"><div className="brand-mark"><UserRound/></div><span className="eyebrow">Choose work context</span><h2 id="role-title">How are you working today?</h2><p>Your data and available actions will match this role. You can switch anytime.</p>{error&&<div role="alert" className="alert error">{error}</div>}<div className="role-grid">{boot.user.roles.map(role=><button key={role} className={`role-choice ${choice===role?'selected':''}`} onClick={()=>setChoice(role)}><span>{role==='administrator'?<ShieldCheck/>:role==='dispatcher'?<Activity/>:role==='requester'?<ClipboardList/>:<UserRound/>}</span><div><strong>{roleNames[role]||statusLabel(role)}</strong><small>{role==='requester'?'Track and manage your requests':'View assigned operations and responsibilities'}</small></div></button>)}</div><button className="primary full" onClick={apply} disabled={!choice}>Continue as {roleNames[choice]}</button></section></div>}

function LocalMap({operations}:{operations:AnyObj}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{if(!ref.current)return;const protocol=new Protocol();maplibregl.addProtocol('pmtiles',protocol.tile);const map=new maplibregl.Map({container:ref.current,center:[77.5946,12.9716],zoom:10,attributionControl:false,style:{version:8,sources:{local:{type:'vector',url:'pmtiles:///maps/bangalore.pmtiles'}},layers:[{id:'background',type:'background',paint:{'background-color':'#e8efeb'}},{id:'roads',type:'line',source:'local','source-layer':'transportation',paint:{'line-color':'#c6d1cc','line-width':1}}]}});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.on('load',()=>{const points=[...(operations.locations||[]).map((x:AnyObj)=>({...x.coordinate,label:x.name,type:'location'})),...(operations.workers||[]).filter((x:AnyObj)=>x.latestLocation).map((x:AnyObj)=>({...x.latestLocation,label:x.fullName||'Worker',type:'worker'}))];for(const p of points){const el=document.createElement('div');el.className=`map-marker ${p.type}`;el.title=p.label;new maplibregl.Marker({element:el}).setLngLat([p.longitude,p.latitude]).setPopup(new maplibregl.Popup({offset:18}).setText(p.label)).addTo(map)}});return()=>{map.remove();maplibregl.removeProtocol('pmtiles')}},[operations]);return <div className="map-wrap"><div ref={ref} className="map" aria-label="Live operations map using local map tiles"/><div className="map-legend"><span><i className="dot location"/>Network location</span><span><i className="dot worker"/>Mobile worker</span></div></div>}

function Overview({boot,onNavigate}:{boot:Bootstrap;onNavigate:(v:string)=>void}){const role=boot.user.activeRole,ops=boot.operations||{},samples=role==='requester'?(boot.requesterSamples||[]):(ops.samples||[]);const exceptions=(ops.exceptions||[]).length;return <><div className="page-head"><div><span className="eyebrow">{new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</span><h1>Good day, {(boot.user.fullName||boot.user.username).split(' ')[0]}</h1><p>Here’s what needs attention across your sample network.</p></div><button className="secondary" onClick={()=>location.reload()}><RefreshCw size={16}/>Refresh</button></div><div className="stats"><article><span className="stat-icon teal"><Beaker/></span><div><small>Active samples</small><strong>{samples.filter((s:AnyObj)=>!['received','cancelled'].includes(s.status)).length}</strong><em>Across the network</em></div></article><article><span className="stat-icon blue"><Route/></span><div><small>Routes in progress</small><strong>{(ops.routes||[]).filter((x:AnyObj)=>x.status!=='completed').length}</strong><em>On active plans</em></div></article><article><span className="stat-icon amber"><AlertTriangle/></span><div><small>Exceptions</small><strong>{exceptions}</strong><em>{exceptions?'Needs review':'No critical issues'}</em></div></article><article><span className="stat-icon purple"><Users/></span><div><small>Available workers</small><strong>{(ops.workers||[]).filter((x:AnyObj)=>x.available).length}</strong><em>{(ops.workers||[]).length} visible</em></div></article></div>{(role==='administrator'||role==='dispatcher')&&<div className="grid dashboard-grid"><section className="panel map-panel"><header><div><h2>Live network</h2><p>Workers, nodes and laboratories</p></div><button className="text-btn" onClick={()=>onNavigate('monitor')}>Open monitor <ChevronRight size={15}/></button></header><LocalMap operations={ops}/></section><section className="panel attention"><header><div><h2>Needs attention</h2><p>Operational exceptions</p></div><Badge value={String(exceptions)} tone="count"/></header>{exceptions?(ops.exceptions||[]).slice(0,4).map((e:AnyObj)=><div className="attention-item" key={e.sampleId}><span><AlertTriangle/></span><div><strong>{e.reason||'Sample exception'}</strong><small>Sample {e.sampleId?.slice(0,8)}</small></div><ChevronRight/></div>):<Empty title="Everything looks healthy" detail="New exceptions will appear here."/>}</section></div>}<section className="panel recent"><header><div><h2>{role==='requester'?'Your samples':'Recent samples'}</h2><p>Latest activity and delivery health</p></div><button className="text-btn" onClick={()=>onNavigate('work')}>View all <ChevronRight size={15}/></button></header><SampleTable samples={samples.slice(0,6)} onSelect={()=>onNavigate('work')}/></section></>}
function SampleTable({samples,onSelect}:{samples:AnyObj[];onSelect:(s:AnyObj)=>void}){if(!samples.length)return <Empty title="No samples yet" detail="Samples will appear here once requests are created."/>;return <div className="table-scroll"><table><thead><tr><th>Sample</th><th>Status</th><th>Current holder</th><th>Deadline</th><th>Location</th><th></th></tr></thead><tbody>{samples.map(s=><tr key={s.sampleId}><td><span className="id-cell"><FlaskConical/> <strong>{s.sampleId.slice(0,8).toUpperCase()}</strong></span></td><td><Badge value={s.status}/></td><td>{s.currentHolderId?<span className="mono">{s.currentHolderId.slice(0,8)}</span>:'Unassigned'}</td><td>{fmt(s.deliveryDeadline)}</td><td><span className={s.locationStale?'stale':'fresh'}>{s.locationStale?'Stale':'Current'}</span></td><td><button aria-label={`View sample ${s.sampleId}`} className="icon-button" onClick={()=>onSelect(s)}><ChevronRight/></button></td></tr>)}</tbody></table></div>}

function WorkView({role,notify}:{role:string;notify:(s:string)=>void}){const [work,setWork]=useState<AnyObj>({pending:[],inProgress:[],completed:[]});const [tab,setTab]=useState('inProgress');const [selected,setSelected]=useState<AnyObj|null>(null);const [error,setError]=useState('');async function load(){try{setWork(await api('/api/list-role-work',{role}));setError('')}catch(e){setError((e as Error).message)}}useEffect(()=>{load()},[role]);async function accept(id:string){try{await api('/api/accept-assignment',{assignmentId:id,idempotencyKey:crypto.randomUUID()});notify('Assignment accepted');load()}catch(e){setError((e as Error).message)}}async function open(item:AnyObj){setSelected(item);if(item.sampleId)try{const life=await api('/api/read-sample-lifecycle',{sampleId:item.sampleId});setSelected({...item,lifecycle:life})}catch{}}const items=work[tab]||[];return <><div className="page-head"><div><span className="eyebrow">Role work</span><h1>My work</h1><p>Current offers, active responsibilities and completed history.</p></div><button className="secondary" onClick={load}><RefreshCw size={16}/>Refresh</button></div>{error&&<div role="alert" className="alert error"><AlertTriangle/>{error}</div>}<section className="panel"><div className="tabs" role="tablist">{[['pending','Offers'],['inProgress','In progress'],['completed','Past work']].map(([k,n])=><button role="tab" aria-selected={tab===k} key={k} onClick={()=>setTab(k)}>{n}<span>{(work[k]||[]).length}</span></button>)}</div>{!items.length?<Empty title={`No ${tab==='completed'?'past':'current'} work`} detail="Work assigned under this role will appear here."/>:<div className="work-list">{items.map((x:AnyObj)=><article key={x.assignmentId||x.sampleId||x.journeyId} className="work-card"><span className="work-icon">{x.kind==='sample'?<FlaskConical/>:x.kind==='laboratory'?<Beaker/>:<Route/>}</span><div className="work-main"><div><Badge value={x.kind||'sample'} tone="kind"/><strong>{statusLabel(x.kind||'sample')} · {(x.assignmentId||x.sampleId||x.journeyId).slice(0,8).toUpperCase()}</strong></div><small>Status <b>{statusLabel(x.status)}</b>{x.offerExpiresAt&&<> · Offer expires {fmt(x.offerExpiresAt)}</>}</small></div>{tab==='pending'&&x.assignmentId&&<button className="primary compact" onClick={()=>accept(x.assignmentId)}>Accept</button>}<button className="icon-button" aria-label="View work history" onClick={()=>open(x)}><ChevronRight/></button></article>)}</div>}</section>{selected&&<DetailDrawer item={selected} close={()=>setSelected(null)}/>}</>}
function DetailDrawer({item,close}:{item:AnyObj;close:()=>void}){const life=item.lifecycle;const history=life?.timeline||item.history||[];return <div className="drawer-backdrop" onClick={close}><aside className="drawer" aria-label="Work details" onClick={e=>e.stopPropagation()}><header><div><span className="eyebrow">Sample detail</span><h2>{(item.sampleId||item.assignmentId).slice(0,8).toUpperCase()}</h2></div><button aria-label="Close details" className="icon-button" onClick={close}><X/></button></header><div className="detail-status"><Badge value={life?.status||item.status}/>{life?.exception&&<Badge value="exception"/>}</div><div className="detail-grid"><div><small>Custodian</small><strong>{life?.currentHolderId?.slice(0,8)||item.currentHolderId?.slice(0,8)||'Not assigned'}</strong></div><div><small>Location update</small><strong className={life?.locationStale?'stale':'fresh'}>{life?.locationStale?'Stale':'Current'}</strong></div><div><small>Route progress</small><strong>{(life?.completedLegIds||[]).length} legs complete</strong></div><div><small>Sealed</small><strong>{life?.sealed?'Yes':'No'}</strong></div></div>{life?.exception&&<div className="alert warning"><AlertTriangle/>{life.exception.reason||'Handling exception flagged'}</div>}<h3>Status timeline</h3><div className="timeline">{history.length?history.map((h:AnyObj,i:number)=><div className="timeline-row" key={h.eventId||i}><span><i/></span><div><strong>{statusLabel(h.action)}</strong><small>{fmt(h.occurredAt)} · {roleNames[h.role]||statusLabel(h.role)}</small></div></div>):<Empty title="No status history" detail="Lifecycle events will appear here."/>}</div></aside></div>}

function RequestView({notify}:{notify:(s:string)=>void}){const initial={originType:'home',latitude:'12.9716',longitude:'77.5946',sampleTypeId:'',requestedAt:new Date().toISOString().slice(0,16),deliveryDeadline:new Date(Date.now()+6*3600000).toISOString().slice(0,16),earliestCollectionAt:'',latestCollectionAt:'',containerType:'standard vial',temperatureMinC:'15',temperatureMaxC:'25'};const [f,setF]=useState(initial);const [result,setResult]=useState<AnyObj|null>(null);const [error,setError]=useState('');function payload(){if(!f.sampleTypeId)throw new Error('Sample type ID is required');if(new Date(f.deliveryDeadline)<=new Date(f.requestedAt))throw new Error('Delivery deadline must be after the request time');return {origin:{latitude:+f.latitude,longitude:+f.longitude},originType:f.originType,sampleTypeId:f.sampleTypeId,requestedAt:new Date(f.requestedAt).toISOString(),deliveryDeadline:new Date(f.deliveryDeadline).toISOString(),...(f.earliestCollectionAt?{earliestCollectionAt:new Date(f.earliestCollectionAt).toISOString()}:{}),...(f.latestCollectionAt?{latestCollectionAt:new Date(f.latestCollectionAt).toISOString()}:{}),containerType:f.containerType,temperatureMinC:+f.temperatureMinC,temperatureMaxC:+f.temperatureMaxC}}async function run(create=false){setError('');try{const p=payload();const d=await api(create?'/api/create-collection-request':'/api/check-serviceability',create?{...p,idempotencyKey:crypto.randomUUID()}:p);setResult(d);notify(create?'Collection request created':'Serviceability dry run complete')}catch(e){setError((e as Error).message)}}const field=(k:string,v:string)=>setF({...f,[k]:v});return <><div className="page-head"><div><span className="eyebrow">New collection</span><h1>Plan a sample pickup</h1><p>Check coverage first without reserving capacity or creating work.</p></div></div><div className="grid form-layout"><section className="panel form-panel"><header><div><h2>Collection details</h2><p>Collection timing and handling requirements</p></div><span className="step">1</span></header>{error&&<div role="alert" className="alert error"><AlertTriangle/>{error}</div>}<div className="form-grid"><label>Origin type<select value={f.originType} onChange={e=>field('originType',e.target.value)}><option value="home">Patient home</option><option value="clinic">Clinic</option></select></label><label>Sample type ID<input value={f.sampleTypeId} onChange={e=>field('sampleTypeId',e.target.value)} placeholder="UUID from sample type catalogue" required/></label><label>Latitude<input type="number" step="any" value={f.latitude} onChange={e=>field('latitude',e.target.value)}/></label><label>Longitude<input type="number" step="any" value={f.longitude} onChange={e=>field('longitude',e.target.value)}/></label><label>Requested at<input type="datetime-local" value={f.requestedAt} onChange={e=>field('requestedAt',e.target.value)}/></label><label>Delivery deadline<input type="datetime-local" value={f.deliveryDeadline} onChange={e=>field('deliveryDeadline',e.target.value)}/></label><label>Earliest collection<input type="datetime-local" value={f.earliestCollectionAt} onChange={e=>field('earliestCollectionAt',e.target.value)}/></label><label>Latest collection<input type="datetime-local" value={f.latestCollectionAt} onChange={e=>field('latestCollectionAt',e.target.value)}/></label><label>Container<input value={f.containerType} onChange={e=>field('containerType',e.target.value)}/></label><div className="split-fields"><label>Min °C<input type="number" value={f.temperatureMinC} onChange={e=>field('temperatureMinC',e.target.value)}/></label><label>Max °C<input type="number" value={f.temperatureMaxC} onChange={e=>field('temperatureMaxC',e.target.value)}/></label></div></div><div className="form-actions"><button className="secondary" onClick={()=>run(false)}><Search/>Check serviceability</button><button className="primary" disabled={!result?.serviceable} onClick={()=>run(true)}>Create request <ChevronRight/></button></div></section><aside className="panel result-panel"><header><div><h2>Serviceability</h2><p>Network-only dry run</p></div><Gauge/></header>{!result?<Empty title="Ready to check" detail="Complete the details to validate coverage, handling, capacity and deadline."/>:<div className={`service-result ${result.serviceable?'yes':'no'}`}><span>{result.serviceable?<PackageCheck/>:<AlertTriangle/>}</span><h3>{result.serviceable?'Serviceable':'Not serviceable'}</h3><p>{statusLabel(result.reason)}</p><dl><div><dt>Calculation version</dt><dd>v{result.serviceabilityVersion}</dd></div><div><dt>Estimated arrival</dt><dd>{fmt(result.estimatedArrivalAt)}</dd></div><div><dt>Target laboratory</dt><dd className="mono">{result.targetLaboratoryId?.slice(0,8)||'—'}</dd></div></dl><small>This check creates no request, assignment, journey, or reservation.</small></div>}</aside></div></>}

function Monitor({operations}:{operations:AnyObj}){const cats=[['Samples',operations.samples||[],FlaskConical],['Workers',operations.workers||[],Users],['Locations',operations.locations||[],MapPin],['Routes',operations.routes||[],Route],['Exceptions',operations.exceptions||[],AlertTriangle]];return <><div className="page-head"><div><span className="eyebrow">Control centre</span><h1>Network monitor</h1><p>Live operational state across samples, people, routes and capacity.</p></div><Badge value="live" tone="live"/></div><div className="monitor-layout"><section className="panel monitor-map"><LocalMap operations={operations}/></section><aside className="monitor-categories">{cats.map(([name,items,Icon]:any)=><article className="panel category-card" key={name}><span><Icon/></span><div><small>{name}</small><strong>{items.length}</strong></div><ChevronRight/></article>)}</aside></div><section className="panel"><header><div><h2>Sample visibility</h2><p>Custodian and location freshness</p></div></header><SampleTable samples={operations.samples||[]} onSelect={()=>{}}/></section></>}

function AuditView(){const [query,setQuery]=useState('');const [entries,setEntries]=useState<AnyObj[]>([]);const [error,setError]=useState('');async function search(){try{const d=await api('/api/search-audit-trail',{query,limit:100,offset:0,order:'newest_first'});setEntries(d.entries);setError('')}catch(e){setError((e as Error).message)}}useEffect(()=>{search()},[]);return <><div className="page-head"><div><span className="eyebrow">Compliance</span><h1>Audit trail</h1><p>Search immutable activity across requests, samples and operations.</p></div></div><section className="panel"><div className="searchbar"><Search/><input aria-label="Search audit history" value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()} placeholder="Search action or entity ID"/><button className="primary" onClick={search}>Search</button></div>{error&&<div className="alert error">{error}</div>}{entries.length?<div className="audit-list">{entries.map(e=><article key={e.auditId}><span className={`audit-dot ${e.success?'ok':'bad'}`}/><div><strong>{statusLabel(e.action)}</strong><small>{e.entityType} · <span className="mono">{e.entityId}</span></small></div><div className="audit-meta"><Badge value={e.actorRole} tone="kind"/><time>{fmt(e.occurredAt)}</time></div></article>)}</div>:<Empty title="No audit records found" detail="Try a broader search or perform an operation."/>}</section></>}

function CapacityView({role,notify}:{role:string;notify:(s:string)=>void}){const [resource,setResource]=useState('');const [regular,setRegular]=useState('10');const [cooled,setCooled]=useState('4');const [error,setError]=useState('');async function save(){try{await api('/api/configure-capacity',{resourceId:resource,capacityUnits:+regular,cooledCapacityUnits:+cooled});notify('Capacity configuration saved');setError('')}catch(e){setError((e as Error).message)}}return <><div className="page-head"><div><span className="eyebrow">{role==='laboratory_team'?'Laboratory intake':'Network configuration'}</span><h1>Capacity</h1><p>Configure regular and cooled units without overbooking reservations.</p></div></div><section className="panel form-panel narrow"><header><div><h2>Capacity pool</h2><p>Available units update after accounting for reservations.</p></div><Boxes/></header>{error&&<div className="alert error">{error}</div>}<label>Node, laboratory, or connection ID<input value={resource} onChange={e=>setResource(e.target.value)} placeholder="Resource UUID"/></label><div className="form-grid"><label>Regular units<input type="number" min="0" value={regular} onChange={e=>setRegular(e.target.value)}/></label><label>Cooled units<input type="number" min="0" value={cooled} onChange={e=>setCooled(e.target.value)}/></label></div><button className="primary" onClick={save}>Save capacity</button></section></>}

function App(){const [boot,setBoot]=useState<Bootstrap|null>(null);const [loading,setLoading]=useState(true);const [page,setPage]=useState('overview');const [toast,setToast]=useState('');const [mobile,setMobile]=useState(false);async function load(){setLoading(true);try{setBoot(await api('/api/ui/bootstrap'))}catch{localStorage.removeItem('labflow_token');setBoot(null)}finally{setLoading(false)}}useEffect(()=>{if(localStorage.getItem('labflow_token'))load();else setLoading(false)},[]);async function switchRole(role:string){await api('/api/select-active-role',{role});setPage('overview');load()}function signout(){localStorage.removeItem('labflow_token');setBoot(null)}if(loading)return <div className="splash"><div className="brand-mark"><FlaskConical/></div><RefreshCw className="spin"/></div>;if(!boot)return <Login onLogin={load}/>;if(boot.user.roleSelectionRequired)return <RolePicker boot={boot} onDone={load}/>;const role=boot.user.activeRole,ops=boot.operations||{};const nav=[['overview','Overview',Gauge],['work','My work',ClipboardList],...(role==='requester'?[['request','New request',Beaker] as any]:[]),...(['administrator','dispatcher'].includes(role)?[['monitor','Network monitor',Map],['audit','Audit trail',History]] as any:[]),...(['administrator','node_handler','laboratory_team'].includes(role)?[['capacity','Capacity',Boxes]] as any:[])];return <div className="app-shell"><aside className={`sidebar ${mobile?'open':''}`}><div className="logo"><span><FlaskConical/></span><strong>LabFlow</strong><button aria-label="Close menu" onClick={()=>setMobile(false)}><X/></button></div><div className="role-context"><small>Working as</small><select aria-label="Active role" value={role} onChange={e=>switchRole(e.target.value)}>{boot.user.roles.map(r=><option key={r} value={r}>{roleNames[r]||r}</option>)}</select></div><nav aria-label="Primary navigation">{nav.map(([id,label,Icon]:any)=><button key={id} className={page===id?'active':''} onClick={()=>{setPage(id);setMobile(false